options=read('/input/options')
result=[]
for c in combinations(options,3):
  sel=list(c)
  sel_ids=[x['id'] for x in sel]
  workers=[x['worker'] for x in sel]
  jobs=[x['job'] for x in sel]
  # Check unique workers and jobs
  unique_workers=0
  unique_jobs=0
  for w in workers:
    count_w=0
    for w2 in workers:
      if w==w2:
        count_w+=1
    if count_w==1:
      unique_workers+=1
  for j in jobs:
    count_j=0
    for j2 in jobs:
      if j==j2:
        count_j+=1
    if count_j==1:
      unique_jobs+=1
  if unique_workers!=3: continue
  if unique_jobs!=3: continue
  # Check cover job
  job_set=[]
  for j in jobs:
    if j not in job_set:
      job_set=job_set+[j]
  cover_jobs=['j0','j1','j2']
  cover_ok=True
  for cj in cover_jobs:
    found=False
    for j in job_set:
      if j==cj:
        found=True
    if not found:
      cover_ok=False
  if not cover_ok: continue
  # Check requires
  valid_requires=True
  for x in sel:
    for r in x['requires']:
      found_r=False
      for sid in sel_ids:
        if sid==r:
          found_r=True
      if not found_r:
        valid_requires=False
        break
    if not valid_requires:
      break
  if not valid_requires: continue
  # Check conflicts
  conflict_found=False
  for x in sel:
    for c_id in x['conflicts']:
      for sid in sel_ids:
        if sid==c_id:
          conflict_found=True
          break
      if conflict_found:
        break
    if conflict_found:
      break
  if conflict_found: continue
  if len(sel)!=3: continue
  result=sel_ids
  break
